1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	};
6	
7	export type Scenario = {
8	  customer: { yearsWithMHPCO: number };
9	  steps: { op: string; items: Item[] }[];
10	};
11	
12	export type ScenarioResult = {
13	  results: { premium: number }[];
14	};
15	
16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	};
21	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
22	
23	const percentOf = (amount: number, percent: number): number =>
24	  (amount * percent) / 100;
25	
26	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
27	
28	const basePremiumFor = (items: Item[]): number =>
29	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
30	
31	const quotePremium = (items: Item[]): number => {
32	  const basePremium = basePremiumFor(items);
33	  const withFirstInsuranceSurcharge =
34	    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
35	  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
36	};
37	
38	export const runScenario = (scenario: Scenario): ScenarioResult => ({
39	  results: scenario.steps.map((step) => ({
40	    premium: quotePremium(step.items),
41	  })),
42	});
43

